use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Sha256,Digest};const R:&str="/home/ubuntu/src/zopro-perf-work/group-admission213";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn main(){let r=Path::new(R);let old=Path::new("/home/ubuntu/src/zopro-perf-work/group-cpu211");let plan=read(old.join("smoke-plan.json"));let mut pins:BTreeMap<String,String>=serde_json::from_value(read(old.join("build-pins.json"))).unwrap();let mut steps=vec![];let mut jobs=vec![];let sdk=old.join("build-run/candidate-sdk");assert_eq!(hash(&sdk),"84a472c6cd1a1eca40c9010d330aeea870ceb8e54381384bd163c2b626b3a6fe");
for b in[false,true]{let arm=if b{"ON"}else{"OFF"};let name=format!("smoke-b{}-t1-block0",usize::from(b));let source=plan["steps"].as_array().unwrap().iter().find(|s|s["name"]==name).unwrap();let mut s=source.clone();let mut v=plan["steps"].as_array().unwrap().iter().find(|s|s["name"]==format!("verify-{name}")).unwrap().clone();let pd=r.join(format!("proofs/{arm}"));s["name"]=json!(format!("capture-{arm}"));s["argv"][2]=json!("0-31");s["argv"][3]=json!(sdk);s["argv"][7]=json!(pd);s["environment"]["RAYON_NUM_THREADS"]=json!("32");s["environment"]["ZOPRO_CPU_GROUP_TRACE"]=json!("1");s["environment"]["ZOPRO_CPU_WORKSPACE_TRACE"]=json!("1");v["name"]=json!(format!("verify-{arm}"));v["argv"][3]=json!(pd.join("0.proof"));v["argv"][4]=json!(pd.join("0.public"));jobs.push(json!({"arm":arm,"proof_dir":pd,"image":v["argv"][1],"image_sha256":v["argv"][2],"public_sha256":v["argv"][5]}));for p in[&s["argv"][4],&s["argv"][5],&v["argv"][0]]{let p=p.as_str().unwrap();pins.insert(p.into(),hash(p));}steps.extend([s,v]);}
let seed="/home/ubuntu/src/zopro-perf-work/group-input212/proof-sha256-after-audit.json";assert_eq!(hash(seed),"616aa4f0fa5259f893875bad99585b78c71366cbaebc65fc044586c85f7d1a5a");for p in[sdk,r.join("protocol.md"),r.join("prepare.rs"),Path::new(seed).to_path_buf()]{pins.insert(p.display().to_string(),hash(p));}fs::write(r.join("jobs.json"),serde_json::to_vec_pretty(&jobs).unwrap()).unwrap();fs::write(r.join("pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(r.join("plan.json"),serde_json::to_vec_pretty(&json!({"version":1,"source_pins":r.join("pins.json"),"steps":steps})).unwrap()).unwrap();println!("ExactSDK2admissionaudits+2verifiersprepared;answerunconstrained,timingignored");}
